package com.hms.auth;
import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.nio.charset.StandardCharsets; import java.util.*; import org.springframework.core.env.Environment; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.web.filter.OncePerRequestFilter;
public class BearerTokenFilter extends OncePerRequestFilter {private final String secret;public BearerTokenFilter(Environment env){secret=env.getProperty("HMS_AUTH_SECRET","development-only-change-me");} protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{String header=request.getHeader("Authorization");if(header!=null&&header.startsWith("Bearer ")){try{String raw=new String(Base64.getUrlDecoder().decode(header.substring(7)),StandardCharsets.UTF_8);String[] parts=raw.split("\\.");if(parts.length==2){String[] fields=parts[0].split("\\|");if(fields.length==4&&Long.parseLong(fields[3])>System.currentTimeMillis()/1000&&MessageSigner.matches(parts[0],parts[1],secret)){var auth=new UsernamePasswordAuthenticationToken(fields[0],null,List.of(new SimpleGrantedAuthority("ROLE_"+fields[2])));SecurityContextHolder.getContext().setAuthentication(auth);}}}catch(Exception ignored){SecurityContextHolder.clearContext();}}chain.doFilter(request,response);}}
